// Import getPendingRefreshToken from hooks/service.
const pendingAtMount = React.useRef(getPendingRefreshToken());
const [waitingForRefresh, setWaitingForRefresh] = React.useState(
  Boolean(pendingAtMount.current)
);
React.useEffect(() => {
  let mounted = true;
  const settled = () => {
    if (mounted) setWaitingForRefresh(false);
  };
  pendingAtMount.current?.then(settled, settled);
  return () => { mounted = false; };
}, []);

